```python
import json
import asyncio
import threading
import time
import logging
from datetime import datetime
from typing import List, Dict, Any, Optional, Union
from abc import ABC, abstractmethod
from enum import Enum

import openai
from pydantic import BaseModel, Field
from loguru import logger

class MemoryCategoryType(str, Enum):
    FACT = "fact"
    PREFERENCE = "preference"
    SKILL = "skill"
    CONTEXT = "context"
    RULE = "rule"

class MemoryClassification(str, Enum):
    ESSENTIAL = "essential"
    CONTEXTUAL = "contextual"
    CONVERSATIONAL = "conversational"
    REFERENCE = "reference"
    PERSONAL = "personal"
    CONSCIOUS_INFO = "conscious-info"

class MemoryImportanceLevel(str, Enum):
    CRITICAL = "critical"
    HIGH = "high"
    MEDIUM = "medium"
    LOW = "low"

class MemorySearchQuery(BaseModel):
    query_text: str
    intent: str
    entity_filters: List[str] = Field(default_factory=list)
    category_filters: List[MemoryCategoryType] = Field(default_factory=list)
    time_range: Optional[str] = None
    min_importance: float = 0.0
    search_strategy: List[str] = Field(default_factory=lambda: ["keyword_search"])
    expected_result_types: List[str] = Field(default_factory=lambda: ["any"])

class ProcessedLongTermMemory(BaseModel):
    content: str
    summary: str
    classification: MemoryClassification
    importance: MemoryImportanceLevel
    topic: Optional[str] = None
    entities: List[str] = Field(default_factory=list)
    keywords: List[str] = Field(default_factory=list)
    is_user_context: bool = False
    is_preference: bool = False
    is_skill_knowledge: bool = False
    is_current_project: bool = False
    session_id: str
    confidence_score: float = 0.0
    classification_reason: str
    promotion_eligible: bool = False
    extraction_timestamp: datetime

class ConversationContext(BaseModel):
    session_id: str
    model_used: str
    current_projects: List[str] = Field(default_factory=list)
    relevant_skills: List[str] = Field(default_factory=list)
    topic_thread: Optional[str] = None

class DatabaseManager(ABC):
    @abstractmethod
    def _get_connection(self):
        pass

    @abstractmethod
    def SessionLocal(self):
        pass

    @abstractmethod
    def get_conscious_memories(self, user_id: str) -> List[Dict]:
        pass

    @abstractmethod
    def get_unprocessed_conscious_memories(self, user_id: str) -> List[Dict]:
        pass

    @abstractmethod
    def store_short_term_memory(self, memory_id: str, processed_data: str, importance_score: float, category_primary: str, retention_type: str, user_id: str, expires_at: Optional[str], searchable_content: str, summary: str, is_permanent_context: bool) -> bool:
        pass

    @abstractmethod
    def search_short_term_memory(self, query: str, user_id: str, limit: int) -> List[Dict]:
        pass

    @abstractmethod
    def find_short_term_memory_by_id(self, memory_id: str, user_id: str) -> Optional[Dict]:
        pass

    @abstractmethod
    def mark_conscious_memories_processed(self, memory_ids: List[str], user_id: str) -> bool:
        pass

    @abstractmethod
    def search_memories(self, query: str, user_id: str, limit: int) -> List[Dict[str, Any]]:
        pass

class MemorySearchEngine:
    SYSTEM_PROMPT = """You are a Memory Search Agent responsible for understanding user queries and planning effective memory retrieval strategies.
Your primary functions:
1. **Analyze Query Intent**: Understand what the user is actually looking for
2. **Extract Search Parameters**: Identify key entities, topics, and concepts
3. **Plan Search Strategy**: Recommend the best approach to find relevant memories
4. **Filter Recommendations**: Suggest appropriate filters for category, importance, etc.
**MEMORY CATEGORIES AVAILABLE:**
- **fact**: Factual information, definitions, technical details, specific data points
- **preference**: User preferences, likes/dislikes, settings, personal choices, opinions
- **skill**: Skills, abilities, competencies, learning progress, expertise levels
- **context**: Project context, work environment, current situations, background info
- **rule**: Rules, policies, procedures, guidelines, constraints
**SEARCH STRATEGIES:**
- **keyword_search**: Direct keyword/phrase matching in content
- **entity_search**: Search by specific entities (people, technologies, topics)
- **category_filter**: Filter by memory categories
- **importance_filter**: Filter by importance levels
- **temporal_filter**: Search within specific time ranges
- **semantic_search**: Conceptual/meaning-based search
**QUERY INTERPRETATION GUIDELINES:**
- "What did I learn about X?" → Focus on facts and skills related to X
- "My preferences for Y" → Focus on preference category
- "Rules about Z" → Focus on rule category
- "Recent work on A" → Temporal filter + context/skill categories
- "Important information about B" → Importance filter + keyword search
Be strategic and comprehensive in your search planning."""

    def __init__(self, api_key: str | None = None, model: str | None = None, provider_config: Any = None):
        if provider_config:
            self.client = provider_config.create_client()
            self.model = model or provider_config.model or "gpt-4o"
            logger.debug(f"Search engine initialized with model: {self.model}")
            self.provider_config = provider_config
        else:
            self.client = openai.OpenAI(api_key=api_key)
            self.model = model or "gpt-4o"
            self.provider_config = None
        self._supports_structured_outputs = self._detect_structured_output_support()
        self._query_cache = {}
        self._cache_ttl = 300
        self._cache_lock = threading.Lock()
        self._background_executor = None
        self._database_type = None

    def _detect_database_type(self, db_manager):
        if self._database_type is None:
            self._database_type = getattr(db_manager, "database_type", "sql")
            logger.debug(f"MemorySearchEngine: Detected database type: {self._database_type}")
        return self._database_type

    def plan_search(self, query: str, context: str | None = None) -> MemorySearchQuery:
        try:
            cache_key = f"{query}|{context or ''}"
            with self._cache_lock:
                if cache_key in self._query_cache:
                    cached_result, timestamp = self._query_cache[cache_key]
                    if time.time() - timestamp < self._cache_ttl:
                        logger.debug(f"Using cached search plan for: {query}")
                        return cached_result
            prompt = f"[INTERNAL_MEMORI_SEARCH]\nUser query: {query}"
            if context:
                prompt += f"\nAdditional context: {context}"
            search_query = None
            if self._supports_structured_outputs:
                try:
                    completion = self.client.beta.chat.completions.parse(
                        model=self.model,
                        messages=[
                            {"role": "system", "content": self.SYSTEM_PROMPT},
                            {"role": "user", "content": prompt},
                        ],
                        response_format=MemorySearchQuery,
                        temperature=0.1,
                    )
                    if completion.choices[0].message.refusal:
                        logger.warning(f"Search planning refused: {completion.choices[0].message.refusal}")
                        return self._create_fallback_query(query)
                    search_query = completion.choices[0].message.parsed
                except Exception as e:
                    logger.warning(f"Structured outputs failed for search planning, falling back to manual parsing: {e}")
                    self._supports_structured_outputs = False
                    search_query = None
            if search_query is None:
                search_query = self._plan_search_with_fallback_parsing(query)
            with self._cache_lock:
                self._query_cache[cache_key] = (search_query, time.time())
                self._cleanup_cache()
            logger.debug(f"Planned search for query '{query}': intent='{search_query.intent}', strategies={search_query.search_strategy}")
            return search_query
        except Exception as e:
            logger.error(f"Search planning failed: {e}")
            return self._create_fallback_query(query)

    def execute_search(self, query: str, db_manager, user_id: str = "default", limit: int = 10) -> list[dict[str, Any]]:
        try:
            db_type = self._detect_database_type(db_manager)
            search_plan = self.plan_search(query)
            logger.debug(f"Search plan for '{query}': strategies={search_plan.search_strategy}, entities={search_plan.entity_filters}, db_type={db_type}")
            all_results = []
            seen_memory_ids = set()
            logger.debug(f"Executing direct SearchService search using {db_type}")
            try:
                primary_results = db_manager.search_memories(query=search_plan.query_text or query, user_id=user_id, limit=limit)
                logger.debug(f"Direct SearchService returned {len(primary_results)} results")
            except Exception as e:
                logger.error(f"SearchService direct access failed: {e}")
                primary_results = []
            for result in primary_results:
                if isinstance(result, dict) and result.get("memory_id") not in seen_memory_ids:
                    seen_memory_ids.add(result["memory_id"])
                    result["search_strategy"] = f"{db_type}_unified_search"
                    result["search_reasoning"] = f"Direct {db_type} database search"
                    all_results.append(result)
            if len(all_results) < limit and search_plan.entity_filters:
                logger.debug(f"Adding targeted keyword search for: {search_plan.entity_filters}")
                keyword_results = self._execute_keyword_search(search_plan, db_manager, user_id, limit - len(all_results))
                for result in keyword_results:
                    if isinstance(result, dict) and result.get("memory_id") not in seen_memory_ids:
                        seen_memory_ids.add(result["memory_id"])
                        result["search_strategy"] = "keyword_search"
                        result["search_reasoning"] = f"Keyword match for: {', '.join(search_plan.entity_filters)}"
                        all_results.append(result)
            if len(all_results) < limit and (search_plan.category_filters or "category_filter" in search_plan.search_strategy):
                logger.debug(f"Adding category search for: {[c.value for c in search_plan.category_filters]}")
                category_results = self._execute_category_search(search_plan, db_manager, user_id, limit - len(all_results))
                for result in category_results:
                    if isinstance(result, dict) and result.get("memory_id") not in seen_memory_ids:
                        seen_memory_ids.add(result["memory_id"])
                        result["search_strategy"] = "category_filter"
                        result["search_reasoning"] = f"Category match: {', '.join([c.value for c in search_plan.category_filters])}"
                        all_results.append(result)
            if len(all_results) < limit and (search_plan.min_importance > 0.0 or "importance_filter" in search_plan.search_strategy):
                logger.debug(f"Adding importance search with min_importance: {search_plan.min_importance}")
                importance_results = self._execute_importance_search(search_plan, db_manager, user_id, limit - len(all_results))
                for result in importance_results:
                    if isinstance(result, dict) and result.get("memory_id") not in seen_memory_ids:
                        seen_memory_ids.add(result["memory_id"])
                        result["search_strategy"] = "importance_filter"
                        result["search_reasoning"] = f"High importance (≥{search_plan.min_importance})"
                        all_results.append(result)
            valid_results = []
            for result in all_results:
                if isinstance(result, dict):
                    valid_results.append(result)
                else:
                    logger.warning(f"Filtering out non-dict search result: {type(result)}")
            all_results = valid_results
            if all_results:
                def safe_created_at_parse(created_at_value):
                    try:
                        if created_at_value is None:
                            return datetime.fromisoformat("2000-01-01")
                        if isinstance(created_at_value, str):
                            return datetime.fromisoformat(created_at_value)
                        if hasattr(created_at_value, "isoformat"):
                            return created_at_value
                        return datetime.fromisoformat("2000-01-01")
                    except (ValueError, TypeError):
                        return datetime.fromisoformat("2000-01-01")
                all_results.sort(
                    key=lambda x: (
                        x.get("importance_score", 0) * 0.7
                        + (datetime.now().replace(tzinfo=None) - safe_created_at_parse(x.get("created_at")).replace(tzinfo=None)).days * -0.001
                    ),
                    reverse=True,
                )
            for result in all_results:
                result["search_metadata"] = {
                    "original_query": query,
                    "interpreted_intent": search_plan.intent,
                    "search_timestamp": datetime.now().isoformat(),
                }
            logger.debug(f"Search executed for '{query}': {len(all_results)} results found")
            return all_results[:limit]
        except Exception as e:
            logger.error(f"Search execution failed: {e}")
            return []

    def _execute_keyword_search(self, search_plan: MemorySearchQuery, db_manager, user_id: str, limit: int) -> list[dict[str, Any]]:
        keywords = search_plan.entity_filters
        if not keywords:
            keywords = [word.strip() for word in search_plan.query_text.split() if len(word.strip()) > 2]
        search_terms = " ".join(keywords)
        try:
            results = db_manager.search_memories(query=search_terms, user_id=user_id, limit=limit)
            if not isinstance(results, list):
                logger.warning(f"Search returned non-list result: {type(results)}")
                return []
            valid_results = []
            for result in results:
                if isinstance(result, dict):
                    valid_results.append(result)
                else:
                    logger.warning(f"Search returned non-dict item: {type(result)}")
            return valid_results
        except Exception as e:
            logger.error(f"Keyword search failed: {e}")
            return []

    def _execute_category_search(self, search_plan: MemorySearchQuery, db_manager, user_id: str, limit: int) -> list[dict[str, Any]]:
        categories = [cat.value for cat in search_plan.category_filters] if search_plan.category_filters else []
        if not categories:
            return []
        logger.debug(f"Searching memories by categories: {categories} for user_id: {user_id}")
        try:
            all_results = db_manager.search_memories(query="", user_id=user_id, limit=limit * 3)
        except Exception as e:
            logger.error(f"Category search failed: {e}")
            all_results = []
        logger.debug(f"Retrieved {len(all_results)} total results for category filtering")
        filtered_results = []
        for i, result in enumerate(all_results):
            try:
                memory_category = None
                if "processed_data" in result and result["processed_data"]:
                    processed_data = result["processed_data"]
                    if isinstance(processed_data, str):
                        try:
                            processed_data = json.loads(processed_data)
                        except json.JSONDecodeError:
                            continue
                    if isinstance(processed_data, dict):
                        category_paths = [["category", "primary_category"], ["category"], ["primary_category"], ["metadata", "category"], ["classification", "category"]]
                        for path in category_paths:
                            temp_data = processed_data
                            try:
                                for key in path:
                                    temp_data = temp_data.get(key, {})
                                if isinstance(temp_data, str) and temp_data:
                                    memory_category = temp_data
                                    break
                            except (AttributeError, TypeError):
                                continue
                if not memory_category and "category" in result and result["category"]:
                    memory_category = result["category"]
                if memory_category:
                    if memory_category in categories:
                        filtered_results.append(result)
            except Exception as e:
                logger.debug(f"Error processing result {i+1}: {e}")
                continue
        return filtered_results[:limit]

    def _detect_structured_output_support(self) -> bool:
        try:
            if self.provider_config and hasattr(self.provider_config, "base_url"):
                base_url = self.provider_config.base_url
                if base_url:
                    if "localhost" in base_url or "127.0.0.1" in base_url:
                        return False
                    if "api.openai.com" not in base_url:
                        return False
            if self.provider_config and hasattr(self.provider_config, "api_type"):
                if self.provider_config.api_type == "azure":
                    return self._test_azure_structured_outputs_support()
                elif self.provider_config.api_type in ["custom", "openai_compatible"]:
                    return False
            return True
        except Exception as e:
            logger.debug(f"Error detecting structured output support: {e}, defaulting to enabled")
            return True

    def _test_azure_structured_outputs_support(self) -> bool:
        try:
            class TestModel(BaseModel):
                test_field: str
            test_response = self.client.beta.chat.completions.parse(
                model=self.model,
                messages=[{"role": "user", "content": "Say hello"}],
                response_format=TestModel,
                max_tokens=10,
                temperature=0,
            )
            if test_response and hasattr(test_response, "choices") and test_response.choices:
                return True
            else:
                return False
        except Exception:
            return False

    def _plan_search_with_fallback_parsing(self, query: str) -> MemorySearchQuery:
        try:
            prompt = f"[INTERNAL_MEMORI_SEARCH]\nUser query: {query}"
            json_system_prompt = self.SYSTEM_PROMPT + "\n\nIMPORTANT: You MUST respond with a valid JSON object that matches this exact schema:\n" + self._get_search_query_json_schema() + "\n\nRespond ONLY with the JSON object, no additional text or formatting."
            completion = self.client.chat.completions.create(
                model=self.model,
                messages=[
                    {"role": "system", "content": json_system_prompt},
                    {"role": "user", "content": prompt},
                ],
                temperature=0.1,
                max_tokens=1000,
            )
            response_text = completion.choices[0].message.content
            if not response_text:
                raise ValueError("Empty response from model")
            response_text = response_text.strip()
            if response_text.startswith("```
                response_text = response_text[7:]
            if response_text.startswith("```"):
                response_text = response_text[3:]
            if response_text.endswith("```
                response_text = response_text[:-3]
            response_text = response_text.strip()
            try:
                parsed_data = json.loads(response_text)
            except json.JSONDecodeError:
                return self._create_fallback_query(query)
            return self._create_search_query_from_dict(parsed_data, query)
        except Exception:
            return self._create_fallback_query(query)

    def _get_search_query_json_schema(self) -> str:
        return """{
"query_text": "string - Original query text",
"intent": "string - Interpreted intent of the query",
"entity_filters": ["array of strings - Specific entities to search for"],
"category_filters": ["array of strings - Memory categories: fact, preference, skill, context, rule"],
"time_range": "string or null - Time range for search (e.g., last_week)",
"min_importance": "number - Minimum importance score (0.0-1.0)",
"search_strategy": ["array of strings - Recommended search strategies"],
"expected_result_types": ["array of strings - Expected types of results"]
}"""

    def _create_search_query_from_dict(self, data: dict[str, Any], original_query: str) -> MemorySearchQuery:
        try:
            category_filters = []
            raw_categories = data.get("category_filters", [])
            if isinstance(raw_categories, list):
                for cat_str in raw_categories:
                    try:
                        category = MemoryCategoryType(cat_str.lower())
                        category_filters.append(category)
                    except ValueError:
                        pass
            return MemorySearchQuery(
                query_text=data.get("query_text", original_query),
                intent=data.get("intent", "General search (fallback)"),
                entity_filters=data.get("entity_filters", []),
                category_filters=category_filters,
                time_range=data.get("time_range"),
                min_importance=max(0.0, min(1.0, float(data.get("min_importance", 0.0)))),
                search_strategy=data.get("search_strategy", ["keyword_search"]),
                expected_result_types=data.get("expected_result_types", ["any"]),
            )
        except Exception:
            return self._create_fallback_query(original_query)

    def _execute_importance_search(self, search_plan: MemorySearchQuery, db_manager, user_id: str, limit: int) -> list[dict[str, Any]]:
        min_importance = max(search_plan.min_importance, 0.7)
        all_results = db_manager.search_memories(query="", user_id=user_id, limit=limit * 2)
        high_importance_results = [result for result in all_results if result.get("importance_score", 0) >= min_importance]
        return high_importance_results[:limit]

    def _create_fallback_query(self, query: str) -> MemorySearchQuery:
        return MemorySearchQuery(
            query_text=query,
            intent="General search (fallback)",
            entity_filters=[word for word in query.split() if len(word) > 2],
            search_strategy=["keyword_search", "general_search"],
            expected_result_types=["any"],
        )

    def _cleanup_cache(self):
        current_time = time.time()
        expired_keys = [key for key, (_, timestamp) in self._query_cache.items() if current_time - timestamp >= self._cache_ttl]
        for key in expired_keys:
            del self._query_cache[key]

    async def execute_search_async(self, query: str, db_manager, user_id: str = "default", limit: int = 10) -> list[dict[str, Any]]:
        try:
            loop = asyncio.get_event_loop()
            search_plan = await loop.run_in_executor(self._background_executor, self.plan_search, query)
            search_tasks = []
            if search_plan.entity_filters or "keyword_search" in search_plan.search_strategy:
                search_tasks.append(loop.run_in_executor(self._background_executor, self._execute_keyword_search, search_plan, db_manager, user_id, limit))
            if search_plan.category_filters or "category_filter" in search_plan.search_strategy:
                search_tasks.append(loop.run_in_executor(self._background_executor, self._execute_category_search, search_plan, db_manager, user_id, limit))
            if search_tasks:
                results_lists = await asyncio.gather(*search_tasks, return_exceptions=True)
                all_results = []
                seen_memory_ids = set()
                for results in results_lists:
                    if isinstance(results, Exception):
                        continue
                    for result in results:
                        if isinstance(result, dict) and result.get("memory_id") not in seen_memory_ids:
                            seen_memory_ids.add(result["memory_id"])
                            all_results.append(result)
                return all_results[:limit]
            return self.execute_search(query, db_manager, user_id, limit)
        except Exception as e:
            logger.error(f"Async search execution failed: {e}")
            return []

    def execute_search_background(self, query: str, db_manager, user_id: str = "default", limit: int = 10, callback=None):
        def _background_search():
            try:
                results = self.execute_search(query, db_manager, user_id, limit)
                if callback:
                    callback(results)
                return results
            except Exception as e:
                logger.error(f"Background search failed: {e}")
                if callback:
                    callback([])
                return []
        thread = threading.Thread(target=_background_search, daemon=True)
        thread.start()
        return thread

    def search_memories(self, query: str, max_results: int = 5, user_id: str = "default") -> list[dict[str, Any]]:
        return []

    @classmethod
    def create_retrieval_agent(cls, memori_instance=None, api_key: str = None, model: str = "gpt-4o"):
        agent = cls(api_key=api_key, model=model)
        if memori_instance:
            agent._memori_instance = memori_instance
        return agent

def smart_memory_search(query: str, memori_instance, limit: int = 5) -> str:
    try:
        search_engine = MemorySearchEngine()
        results = search_engine.execute_search(query=query, db_manager=memori_instance.db_manager, user_id=memori_instance.user_id, limit=limit)
        if not results:
            return f"No relevant memories found for query: '{query}'"
        output = f"Smart Memory Search Results for: '{query}'\n\n"
        for i, result in enumerate(results, 1):
            try:
                if "processed_data" in result:
                    processed_data = result["processed_data"]
                    if isinstance(processed_data, str):
                        processed_data = json.loads(processed_data)
                    if isinstance(processed_data, dict):
                        summary = processed_data.get("summary", "")
                        category = processed_data.get("category", {}).get("primary_category", "")
                    else:
                        summary = result.get("summary", result.get("searchable_content", "")[:100] + "...")
                        category = result.get("category_primary", "unknown")
                else:
                    summary = result.get("summary", result.get("searchable_content", "")[:100] + "...")
                    category = result.get("category_primary", "unknown")
                importance = result.get("importance_score", 0.0)
                created_at = result.get("created_at", "")
                search_strategy = result.get("search_strategy", "unknown")
                search_reasoning = result.get("search_reasoning", "")
                output += f"{i}. [{str(category).upper()}] {summary}\n"
                output += f" Importance: {importance:.2f} | Created: {created_at}\n"
                output += f" Strategy: {search_strategy}\n"
                if search_reasoning:
                    output += f" Reason: {search_reasoning}\n"
                output += "\n"
            except Exception:
                content = result.get("searchable_content", "Memory content available")[:100]
                output += f"{i}. {content}...\n\n"
        return output.strip()
    except Exception as e:
        logger.error(f"Smart memory search failed: {e}")
        return f"Error in smart memory search: {str(e)}"

