        else:
            self.client = openai.OpenAI(api_key=api_key)
            self.async_client = openai.AsyncOpenAI(api_key=api_key)
            self.model = model or "gpt-4o"
            self.provider_config = None
        self._supports_structured_outputs = self._detect_structured_output_support()
        self._database_type = None

    def _detect_database_type(self, db_manager):
        if self._database_type is None:
            self._database_type = getattr(db_manager, "database_type", "sql")
            logger.debug(f"MemoryAgent: Detected database type: {self._database_type}")
        return self._database_type

    async def process_conversation_async(self, chat_id: str, user_input: str, ai_output: str, context: ConversationContext | None = None, existing_memories: list[str] | None = None) -> ProcessedLongTermMemory:
        try:
            conversation_text = f"User: {user_input}\nAssistant: {ai_output}"
            system_prompt = self.SYSTEM_PROMPT
            if existing_memories:
                dedup_context = "\n\nEXISTING MEMORIES (for deduplication):\n" + "\n".join(existing_memories[:10])
                system_prompt += dedup_context
            context_info = ""
            if context:
                context_info = f"""
CONVERSATION CONTEXT:
- Session: {context.session_id}
- Model: {context.model_used}
- User Projects: {', '.join(context.current_projects) if context.current_projects else 'None specified'}
- Relevant Skills: {', '.join(context.relevant_skills) if context.relevant_skills else 'None specified'}
- Topic Thread: {context.topic_thread or 'General conversation'}
"""
            processed_memory = None
            if self._supports_structured_outputs:
                try:
                    completion = await self.async_client.beta.chat.completions.parse(
                        model=self.model,
                        messages=[
                            {"role": "system", "content": system_prompt},
                            {"role": "user", "content": f"Process this conversation for enhanced memory storage:\n\n{conversation_text}\n{context_info}"},
                        ],
                        response_format=ProcessedLongTermMemory,
                        temperature=0.1,
                    )
                    if completion.choices.message.refusal:
                        logger.warning(f"Memory processing refused for chat {chat_id}: {completion.choices.message.refusal}")
                        return self._create_empty_long_term_memory(context.session_id if context else "default", "Processing refused for safety reasons")
                    processed_memory = completion.choices.message.parsed
                    processed_memory.session_id = context.session_id if context else "default"
                    processed_memory.extraction_timestamp = datetime.now()
                except Exception as e:
                    logger.warning(f"Structured outputs failed for {chat_id}, falling back to manual parsing: {e}")
                    self._supports_structured_outputs = False
                    processed_memory = None
            if processed_memory is None:
                processed_memory = await self._process_with_fallback_parsing(chat_id, system_prompt, conversation_text, context_info)
            logger.debug(f"[AGENT] Processed conversation {chat_id[:8]}... - classification: {processed_memory.classification.value} | importance: {processed_memory.importance.value} | conscious_context: {processed_memory.is_user_context} | promotion_eligible: {processed_memory.promotion_eligible}")
            return processed_memory
        except Exception as e:
            logger.error(f"[AGENT] Memory processing failed for {chat_id[:8]}... - {type(e).__name__}: {e}")
            return self._create_empty_long_term_memory(context.session_id if context else "default", f"Processing failed: {str(e)}")

    def _create_empty_long_term_memory(self, session_id: str, reason: str) -> ProcessedLongTermMemory:
        return ProcessedLongTermMemory(
            content="Processing failed",
            summary="Processing failed",
            classification=MemoryClassification.CONVERSATIONAL,
            importance=MemoryImportanceLevel.LOW,
            session_id=session_id,
            classification_reason=reason,
            confidence_score=0.0,
            extraction_timestamp=datetime.now(),
        )

    async def detect_duplicates(self, new_memory: ProcessedLongTermMemory, existing_memories: list[ProcessedLongTermMemory], similarity_threshold: float = 0.8) -> str | None:
        new_content = new_memory.content.lower().strip()
        new_summary = new_memory.summary.lower().strip()
        for existing in existing_memories:
            existing_content = existing.content.lower().strip()
            existing_summary = existing.summary.lower().strip()
            content_similarity = self._calculate_similarity(new_content, existing_content)
            summary_similarity = self._calculate_similarity(new_summary, existing_summary)
            avg_similarity = (content_similarity + summary_similarity) / 2
            if avg_similarity >= similarity_threshold:
                logger.info(f"[AGENT] Duplicate detected - {avg_similarity:.2f} similarity with {existing.session_id[:8]}...")
                return existing.session_id
        return None

    def _calculate_similarity(self, text1: str, text2: str) -> float:
        if not text1 or not text2:
            return 0.0
        words1 = set(text1.split())
        words2 = set(text2.split())
        if not words1 or not words2:
            return 0.0
        intersection = len(words1.intersection(words2))
        union = len(words1.union(words2))
        return intersection / union if union > 0 else 0.0

    def _detect_structured_output_support(self) -> bool:
        try:
            if self.provider_config and hasattr(self.provider_config, "base_url"):
                base_url = self.provider_config.base_url
                if base_url:
                    if "localhost" in base_url or "127.0.0.1" in base_url:
                        return False
                    if "api.openai.com" not in base_url:
                        return False
            if self.provider_config and hasattr(self.provider_config, "api_type"):
                if self.provider_config.api_type == "azure":
                    return True
                elif self.provider_config.api_type in ["custom", "openai_compatible"]:
                    return False
            return True
        except Exception:
            return True

    async def _process_with_fallback_parsing(self, chat_id: str, system_prompt: str, conversation_text: str, context_info: str) -> ProcessedLongTermMemory:
        try:
            json_system_prompt = system_prompt + "\n\nIMPORTANT: You MUST respond with a valid JSON object that matches this exact schema:\n" + self._get_json_schema_prompt() + "\n\nRespond ONLY with the JSON object, no additional text or formatting."
            completion = await self.async_client.chat.completions.create(
                model=self.model,
                messages=[
                    {"role": "system", "content": json_system_prompt},
                    {"role": "user", "content": f"Process this conversation for enhanced memory storage:\n\n{conversation_text}\n{context_info}"},
                ],
                temperature=0.1,
                max_tokens=2000,
            )
            response_text = completion.choices.message.content
            if not response_text:
                raise ValueError("Empty response from model")
            response_text = response_text.strip()
            if response_text.startswith("```json"):
                response_text = response_text[7:]
            if response_text.startswith("```
                response_text = response_text[3:]
            if response_text.endswith("```"):
                response_text = response_text[:-3]
            response_text = response_text.strip()
            try:
                parsed_data = json.loads(response_text)
            except json.JSONDecodeError as e:
                logger.error(f"Failed to parse JSON response for {chat_id}: {e}")
                return self._create_empty_long_term_memory("default", f"JSON parsing failed: {e}")
            processed_memory = self._create_memory_from_dict(parsed_data, chat_id)
            logger.debug(f"Successfully parsed memory using fallback method for {chat_id}")
            return processed_memory
        except Exception as e:
            logger.error(f"Fallback memory processing failed for {chat_id}: {e}")
            return self._create_empty_long_term_memory("default", f"Fallback processing failed: {str(e)}")

    def _get_json_schema_prompt(self) -> str:
        return """{
"content": "string - The actual memory content",
"summary": "string - Concise summary for search",
"classification": "string - One of: essential, contextual, conversational, reference, personal, conscious-info",
"importance": "string - One of: critical, high, medium, low",
"topic": "string or null - Main topic/subject",
"entities": ["array of strings - People, places, technologies mentioned"],
"keywords": ["array of strings - Key terms for search"],
"is_user_context": "boolean - Contains user personal info",
"is_preference": "boolean - User preference/opinion",
"is_skill_knowledge": "boolean - User's abilities/expertise",
"is_current_project": "boolean - Current work context",
"classification_reason": "string - Why this classification was chosen",
"confidence_score": "number - AI confidence in extraction (0.0-1.0)",
"promotion_eligible": "boolean - Should be promoted to short-term"
}"""

    def _create_memory_from_dict(self, data: dict[str, Any], chat_id: str) -> ProcessedLongTermMemory:
        try:
            classification_str = data.get("classification", "conversational").lower().replace("_", "-")
            try:
                classification = MemoryClassification(classification_str)
            except ValueError:
                classification = MemoryClassification.CONVERSATIONAL
            importance_str = data.get("importance", "medium").lower()
            try:
                importance = MemoryImportanceLevel(importance_str)
            except ValueError:
                importance = MemoryImportanceLevel.MEDIUM
            processed_memory = ProcessedLongTermMemory(
                content=data.get("content", "No content extracted"),
                summary=data.get("summary", "No summary available"),
                classification=classification,
                importance=importance,
                topic=data.get("topic"),
                entities=data.get("entities", []),
                keywords=data.get("keywords", []),
                is_user_context=bool(data.get("is_user_context", False)),
                is_preference=bool(data.get("is_preference", False)),
                is_skill_knowledge=bool(data.get("is_skill_knowledge", False)),
                is_current_project=bool(data.get("is_current_project", False)),
                session_id="default",
                confidence_score=float(data.get("confidence_score", 0.7)),
                classification_reason=data.get("classification_reason", "Extracted via fallback parsing"),
                promotion_eligible=bool(data.get("promotion_eligible", False)),
                extraction_timestamp=datetime.now(),
            )
            return processed_memory
        except Exception as e:
            logger.error(f"Error creating memory from dict: {e}")
            return self._create_empty_long_term_memory("default", f"Memory creation failed: {str(e)}")

    def should_filter_memory(self, memory: ProcessedLongTermMemory, filters: dict[str, Any] | None = None) -> bool:
        if not filters:
            return False
        if "exclude_classifications" in filters:
            if memory.classification in filters["exclude_classifications"]:
                return True
        if "min_importance" in filters:
            importance_map = {"critical": 4, "high": 3, "medium": 2, "low": 1}
            min_level = importance_map.get(filters["min_importance"], 1)
            memory_level = importance_map.get(memory.importance, 1)
            if memory_level < min_level:
                return True
        if "min_confidence" in filters:
            if memory.confidence_score < filters["min_confidence"]:
                return True
        if "exclude_keywords" in filters:
            content_lower = memory.content.lower()
            if any(keyword.lower() in content_lower for keyword in filters["exclude_keywords"]):
                return True
        if "min_content_length" in filters:
            if len(memory.content.strip()) < filters["min_content_length"]:
                return True
        return False

class ConsciousAgent:
    def __init__(self):
